function drawProjection(s){
const routes=new Map();
for(const edge of s.b.edges){const a=anchor(s.b.node(edge.from)),b=anchor(s.b.node(edge.to));if(!a||!b||a.id===b.id)continue;const key=a.id+':'+b.id+':'+edge.kind;
if(!routes.has(key))routes.set(key,{a,b,kind:edge.kind,amount:0,error:false});const r=routes.get(key);r.amount+=edge.amount||0;r.error=r.error||!!edge.error;}
const projectionHTML=[...routes.values()].map(r=>{const {a,b}=r,mid=(a.x+b.x)/2,offset=r.kind==='power'?48:-48,y=(a.y+b.y)/2+offset/2-6,curve='M'+a.x+','+a.y+'Q'+mid+','+((a.y+b.y)/2+offset)+' '+b.x+','+b.y;return '<g><path class="sea-link-base" d="'+curve+'"/><path class="sea-link '+(r.error?'fault':r.kind==='power'?'power':'material')+(r.amount>0&&!r.error?' flowing':'')+'" d="'+curve+'"/><text x="'+mid+'" y="'+y+'" class="sea-route-label">'+(r.error?'배출 정지':fmt(r.amount)+' '+(r.kind==='power'?'kW':'/min'))+'</text></g>';}).join('');
if(projectionHTML!==lastProjection){projection.innerHTML=projectionHTML;lastProjection=projectionHTML;}
// The planning prototype models an eight-second direct transit, not physical navigation.
const fleetHTML=s.fleets.map(n=>{const from=xy(n.location),target=xy(n.travelTarget||n.destination);if(!from)return '';const p=n.status==='이동중'?Math.min(1,n.travel/8):0,x=from.x+(target?target.x-from.x:0)*p,y=from.y+(target?target.y-from.y:0)*p;
return '<g>'+(n.status==='이동중'&&target?'<path class="sea-fleet-route flowing" d="M'+from.x+','+from.y+'L'+target.x+','+target.y+'"/>':'')+'<g transform="translate('+x+' '+y+')"><path class="sea-ship" d="M0-10L7 8L0 4L-7 8Z"/><text x="12" y="28" class="sea-fleet-label">'+esc(n.title)+' / '+esc(n.status)+'</text></g></g>';}).join('');
if(fleetHTML!==lastFleet){fleetLayer.innerHTML=fleetHTML;lastFleet=fleetHTML;}
}
