document.querySelector('#seaTrade').textContent=s.market?'교환 가능 '+s.market.slots.filter(o=>o.stock>0).length+'/6 · 다음 회차 '+Math.max(0,Math.ceil(((s.market.epoch+1)*TradeModel.PERIOD-Date.now())/60000))+'분':'교역 자료 연결 대기';
