const continents=[[[ -168,65],[-140,70],[-125,58],[-124,48],[-117,32],[-105,23],[-88,15],[-80,9],[-77,23],[-65,45],[-52,52],[-70,60],[-100,73],[-140,72]], [[-81,12],[-68,9],[-49,-1],[-35,-7],[-42,-23],[-54,-35],[-68,-55],[-75,-45],[-72,-20],[-80,-4]], [[-17,36],[2,36],[12,33],[33,31],[42,12],[51,11],[43,-13],[32,-28],[18,-35],[10,-20],[6,4],[-12,6],[-17,20]], [[-10,36],[-10,44],[0,51],[8,56],[5,62],[25,71],[45,68],[65,72],[100,77],[150,70],[179,65],[170,51],[146,45],[137,35],[126,40],[120,25],[109,19],[106,8],[98,2],[94,16],[85,23],[77,8],[70,22],[55,25],[42,12],[35,30],[27,40],[15,40]], [[112,-12],[130,-11],[140,-17],[153,-25],[148,-39],[132,-34],[115,-35]], [[-52,60],[-43,60],[-20,75],[-40,83],[-63,76]], [[46,-13],[50,-17],[47,-26],[43,-24]], [[130,32],[137,34],[143,44],[145,43],[140,35]], [[95,5],[106,-6],[117,-8],[129,-5],[140,-7],[151,-4],[141,-10],[124,-10],[110,-8],[100,0]], [[166,-35],[178,-38],[171,-46],[165,-44]]];
function inside(x,y,p){let result=false;for(let i=0,j=p.length-1;i<p.length;j=i++){const a=p[i],b=p[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])result=!result;}return result;}
const land=[];for(let lat=-58;lat<83;lat+=2)for(let lon=-180;lon<180;lon+=2/Math.max(.3,Math.cos(lat*Math.PI/180)))if(continents.some(p=>inside(lon,lat,p)))land.push([lon,lat]);
function project(lon,lat){const a=lon*Math.PI/180+yaw,b=lat*Math.PI/180,x=Math.cos(b)*Math.sin(a),y=Math.sin(b),z=Math.cos(b)*Math.cos(a);return{x,y:y*Math.cos(pitch)-z*Math.sin(pitch),z:y*Math.sin(pitch)+z*Math.cos(pitch)};}
function draw(now){requestAnimationFrame(draw);if(!window.SeaUI?.sites?.planet||!pane.getBoundingClientRect().width){last=now;return;}if(now-last<32)return;const dt=Math.min(.1,(now-last)/1000);last=now;if(!drag&&!pane.classList.contains('sea-still')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){yaw+=dt*.045;rotation++;}const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;const d=Math.min(2,devicePixelRatio);if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);}ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle=window.DebugColors?.resolve('#06151e')||'#06151e';ctx.fillRect(0,0,w,h);const cx=w*.52,cy=h*.53,r=Math.min(w*.42,h*.43);const glow=ctx.createRadialGradient(cx,cy,r*.95,cx,cy,r*1.13);glow.addColorStop(0,'#5abcf955');glow.addColorStop(.45,'#277cba22');glow.addColorStop(1,'#06151e00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,r*1.13,0,Math.PI*2);ctx.fill();const ocean=ctx.createRadialGradient(cx-r*.35,cy-r*.4,0,cx,cy,r);ocean.addColorStop(0,'#183345');ocean.addColorStop(.75,'#0a1d2b');ocean.addColorStop(1,'#08131e');ctx.fillStyle=ocean;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle=window.DebugColors?.resolve('#77c6e8aa')||'#77c6e8aa';ctx.lineWidth=1;ctx.stroke();
function line(points,color,width=1){ctx.beginPath();let pen=false;for(const [lon,lat] of points){const p=project(lon,lat);if(p.z<0){pen=false;continue;}const x=cx+p.x*r,y=cy-p.y*r;if(pen)ctx.lineTo(x,y);else ctx.moveTo(x,y);pen=true;}ctx.strokeStyle=window.DebugColors?.resolve(color)||color;ctx.lineWidth=width;ctx.stroke();}
for(let lat=-60;lat<=60;lat+=30)line(Array.from({length:181},(_,i)=>[-180+i*2,lat]),'#52829b28');for(let lon=-180;lon<180;lon+=30)line(Array.from({length:91},(_,i)=>[lon,-90+i*2]),'#52829b28');
for(const poly of continents){const path=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],steps=Math.ceil(Math.max(Math.abs(b[0]-a[0]),Math.abs(b[1]-a[1])));for(let j=0;j<=steps;j++)path.push([a[0]+(b[0]-a[0])*j/steps,a[1]+(b[1]-a[1])*j/steps]);}line(path,'#78b9d66b',.8);}
for(const [lon,lat] of land){const p=project(lon,lat);if(p.z<=0)continue;ctx.fillStyle='rgba(137,211,241,'+(.2+.75*p.z)+')';ctx.beginPath();ctx.arc(cx+p.x*r,cy-p.y*r,Math.max(.6,r*.003*(.5+p.z)),0,Math.PI*2);ctx.fill();}
const site=project(127,34);marker=null;if(site.z>0){const x=cx+site.x*r,y=cy-site.y*r;marker={x,y};ctx.strokeStyle=window.DebugColors?.resolve('#9bf3d4')||'#9bf3d4';ctx.fillStyle=window.DebugColors?.resolve('#b5ffe1')||'#b5ffe1';ctx.beginPath();ctx.arc(x,y,10,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();ctx.font='500 12px Pretendard';ctx.fillText('07 / 북부 해역',x+18,y-5);ctx.fillStyle=window.DebugColors?.resolve('#90afbd')||'#90afbd';ctx.font='400 10px Pretendard';ctx.fillText(nodes.length+'개 거점',x+18,y+12);}
host.querySelector('.earth-readout').textContent='GLOBAL VIEW / '+nodes.length+' SITES · 1 SECTOR   |   회전 '+Math.round(yaw*180/Math.PI)%360+'°';}
function sync(){host.hidden=!SeaUI.sites.planet;pane.querySelector('#seaPlanet').style.display='none';}
