canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,yaw,pitch,moved:false};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.moved||=Math.hypot(dx,dy)>4;yaw=drag.yaw+dx*.006;pitch=Math.max(-1.3,Math.min(1.3,drag.pitch+dy*.006));});canvas.addEventListener('pointerup',e=>{if(!drag)return;const moved=drag.moved;drag=null;const rect=canvas.getBoundingClientRect();if(!moved&&marker&&Math.hypot(e.clientX-rect.x-marker.x,e.clientY-rect.y-marker.y)<24)SeaUI.sites.home();});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();if(e.deltaY<0)SeaUI.sites.home();},{passive:false});canvas.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')yaw-=.15;if(e.key==='ArrowRight')yaw+=.15;if(e.key==='ArrowUp')pitch=Math.min(1.3,pitch+.1);if(e.key==='ArrowDown')pitch=Math.max(-1.3,pitch-.1);if(e.key==='Enter')SeaUI.sites.home();if(e.key.startsWith('Arrow'))e.preventDefault();});host.querySelector('[data-earth-home]').onclick=()=>SeaUI.sites.home();host.querySelector('[data-earth-reset]').onclick=()=>{yaw=-1.7;pitch=.25;};
