const bounds={left:0,top:0,right:2000,bottom:1520},brake={left:-650,top:-500,right:2650,bottom:2020};
const make=(tag,attrs={})=>{const el=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el;};
const defs=map.querySelector('defs');
const extra=make('g');extra.innerHTML='<pattern id="seaFineGrid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M10 0H0V10" fill="none" stroke="#6c96c2" stroke-opacity=".22" stroke-width=".5"/></pattern><pattern id="seaOuterHatch" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M-6 6L6-6M0 24L24 0M18 30L30 18" stroke="#577fa5" stroke-opacity=".24" stroke-width="1"/></pattern><clipPath id="seaSectorClip"><rect width="1000" height="760"/></clipPath><radialGradient id="seaRadarFill"><stop stop-color="#6ee6e6" stop-opacity=".12"/><stop offset="1" stop-color="#6ee6e6" stop-opacity="0"/></radialGradient>';while(extra.firstChild)defs.append(extra.firstChild);
