function aspect(){return Math.max(.4,map.clientWidth/Math.max(1,map.clientHeight));}
function maxZoom(){return Math.max(4000,2300*aspect());}
view=function(){const v=state.view,cx=clamp(v.x+v.w/2,brake.left,brake.right),cy=clamp(v.y+v.h/2,brake.top,brake.bottom);v.w=clamp(v.w,400,maxZoom());v.h=v.w/aspect();v.x=cx-v.w/2;v.y=cy-v.h/2;previousView();};
new ResizeObserver(()=>{if(map.clientWidth)view();}).observe(map);
